import { cn } from '@/lib/utils'

export type TimelineProps = {
  title?: string
  items: Array<{ date: string; title: string; description?: string }>
  className?: string
}

export function Timeline({ title, items, className }: TimelineProps) {
  return (
    <section
      className={cn('py-16 md:py-24', className)}
      aria-labelledby={title ? 'timeline-title' : undefined}
    >
      <div className="container max-w-4xl">
        {title ? (
          <h2 id="timeline-title" className="mb-10 text-3xl font-bold tracking-tight md:text-4xl">
            {title}
          </h2>
        ) : null}
        <ol className="relative border-l border-border">
          {items.map((item, index) => (
            <li key={`${item.date}-${item.title}`} className="relative ml-7 pb-10 last:pb-0">
              <span
                className="absolute -left-[2.15rem] top-1 flex h-4 w-4 items-center justify-center rounded-full border-4 border-background bg-primary"
                aria-hidden="true"
              />
              <time className="text-sm font-semibold text-primary">{item.date}</time>
              <h3 className="mt-1 text-xl font-semibold">{item.title}</h3>
              {item.description ? (
                <p className="mt-2 leading-7 text-muted-foreground">{item.description}</p>
              ) : null}
              <span className="sr-only">
                Etapa {index + 1} de {items.length}
              </span>
            </li>
          ))}
        </ol>
      </div>
    </section>
  )
}

'use client'

import Image from 'next/image'
import Link from 'next/link'
import { motion, useReducedMotion } from 'framer-motion'
import { Globe, Instagram, Linkedin, Mail, MessageCircle, type LucideIcon } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type TeamSocialType = 'linkedin' | 'instagram' | 'email' | 'whatsapp' | 'website'

export type TeamSectionMember = {
  name: string
  role: string
  image: { src: string; alt?: string }
  bio?: string
  socials?: Array<{ type: TeamSocialType; href: string }>
}

export type TeamSectionProps = {
  title: string
  eyebrow?: string
  description?: string
  members: TeamSectionMember[]
  variant?: 'overlay' | 'cards' | 'minimal' | 'featured'
  columns?: 3 | 4
  action?: { label: string; href: string }
  className?: string
}

const socialMeta: Record<TeamSocialType, { icon: LucideIcon; label: string }> = {
  linkedin: { icon: Linkedin, label: 'LinkedIn' },
  instagram: { icon: Instagram, label: 'Instagram' },
  email: { icon: Mail, label: 'E-mail' },
  whatsapp: { icon: MessageCircle, label: 'WhatsApp' },
  website: { icon: Globe, label: 'Site' },
}

const columnClasses = {
  3: 'sm:grid-cols-2 lg:grid-cols-3',
  4: 'sm:grid-cols-2 lg:grid-cols-4',
}

function socialHref(type: TeamSocialType, href: string) {
  if (type === 'email' && !href.startsWith('mailto:')) return `mailto:${href}`
  return href
}

function Socials({
  member,
  tone = 'default',
  className,
}: {
  member: TeamSectionMember
  tone?: 'default' | 'inverted'
  className?: string
}) {
  if (!member.socials?.length) return null

  return (
    <ul className={cn('flex flex-wrap gap-2', className)}>
      {member.socials.map((social) => {
        const { icon: Icon, label } = socialMeta[social.type]
        const external = social.type !== 'email'

        return (
          <li key={`${social.type}-${social.href}`}>
            <a
              href={socialHref(social.type, social.href)}
              target={external ? '_blank' : undefined}
              rel={external ? 'noreferrer' : undefined}
              aria-label={`${label} de ${member.name}`}
              className={cn(
                'flex h-9 w-9 items-center justify-center rounded-full transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                tone === 'inverted'
                  ? 'bg-white/15 text-white backdrop-blur hover:bg-primary'
                  : 'bg-muted text-muted-foreground hover:bg-primary hover:text-primary-foreground',
              )}
            >
              <Icon className="h-4 w-4" aria-hidden />
            </a>
          </li>
        )
      })}
    </ul>
  )
}

function OverlayCard({ member }: { member: TeamSectionMember }) {
  return (
    <article className="group relative aspect-[3/4] overflow-hidden rounded-3xl bg-muted">
      <Image
        src={member.image.src}
        alt={member.image.alt ?? member.name}
        fill
        className="object-cover transition duration-700 group-hover:scale-105"
        sizes="(min-width: 1024px) 25vw, (min-width: 640px) 50vw, 100vw"
      />
      <div className="absolute inset-0 bg-gradient-to-t from-black/85 via-black/20 to-transparent transition-colors duration-500 md:group-focus-within:from-primary/90 md:group-hover:from-primary/90" />
      <div className="absolute inset-x-0 bottom-0 p-6 text-white">
        <h3 className="text-xl font-bold">{member.name}</h3>
        <p className="text-sm font-medium text-white/80">{member.role}</p>
        <div className="grid transition-all duration-500 md:grid-rows-[0fr] md:opacity-0 md:group-focus-within:grid-rows-[1fr] md:group-focus-within:opacity-100 md:group-hover:grid-rows-[1fr] md:group-hover:opacity-100">
          <div className="min-h-0 overflow-hidden">
            {member.bio ? (
              <p className="mt-3 text-sm leading-6 text-white/85">{member.bio}</p>
            ) : null}
            <Socials member={member} tone="inverted" className="mt-4" />
          </div>
        </div>
      </div>
    </article>
  )
}

function CardsCard({ member }: { member: TeamSectionMember }) {
  return (
    <article className="group flex h-full flex-col overflow-hidden rounded-3xl border bg-card transition duration-300 hover:-translate-y-1 hover:border-primary/40 hover:shadow-xl">
      <div className="relative aspect-[4/5] overflow-hidden bg-muted">
        <Image
          src={member.image.src}
          alt={member.image.alt ?? member.name}
          fill
          className="object-cover transition duration-700 group-hover:scale-105"
          sizes="(min-width: 1024px) 25vw, (min-width: 640px) 50vw, 100vw"
        />
      </div>
      <div className="flex flex-1 flex-col p-6">
        <h3 className="text-lg font-semibold">{member.name}</h3>
        <p className="text-sm font-medium text-primary">{member.role}</p>
        {member.bio ? (
          <p className="mt-3 text-sm leading-6 text-muted-foreground">{member.bio}</p>
        ) : null}
        <Socials member={member} className="mt-auto pt-5" />
      </div>
    </article>
  )
}

function MinimalCard({ member }: { member: TeamSectionMember }) {
  return (
    <article className="group flex flex-col items-center text-center">
      <div className="relative aspect-square w-full max-w-44 overflow-hidden rounded-full bg-muted ring-4 ring-transparent ring-offset-4 ring-offset-background transition duration-300 group-hover:ring-primary">
        <Image
          src={member.image.src}
          alt={member.image.alt ?? member.name}
          fill
          className="object-cover transition duration-700 group-hover:scale-105"
          sizes="176px"
        />
      </div>
      <h3 className="mt-5 text-base font-semibold sm:text-lg">{member.name}</h3>
      <p className="text-sm text-muted-foreground">{member.role}</p>
      <Socials member={member} className="mt-3 justify-center" />
    </article>
  )
}

function FeaturedMember({ member }: { member: TeamSectionMember }) {
  return (
    <article className="grid overflow-hidden rounded-3xl border bg-card md:grid-cols-2">
      <div className="relative aspect-[4/3] bg-muted md:aspect-auto md:min-h-[26rem]">
        <Image
          src={member.image.src}
          alt={member.image.alt ?? member.name}
          fill
          className="object-cover"
          sizes="(min-width: 768px) 50vw, 100vw"
        />
      </div>
      <div className="flex flex-col justify-center p-6 sm:p-8 md:p-12">
        <p className="text-sm font-semibold uppercase tracking-widest text-primary">
          {member.role}
        </p>
        <h3 className="mt-2 text-2xl font-bold tracking-tight md:text-3xl">{member.name}</h3>
        {member.bio ? <p className="mt-4 leading-7 text-muted-foreground">{member.bio}</p> : null}
        <Socials member={member} className="mt-6" />
      </div>
    </article>
  )
}

const cardByVariant = {
  overlay: OverlayCard,
  cards: CardsCard,
  minimal: MinimalCard,
  featured: CardsCard,
}

export function TeamSection({
  title,
  eyebrow,
  description,
  members,
  variant = 'overlay',
  columns = 4,
  action,
  className,
}: TeamSectionProps) {
  const reduceMotion = useReducedMotion()
  const [leader, ...rest] = members
  const list = variant === 'featured' ? rest : members
  const Card = cardByVariant[variant]

  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        <div className="mx-auto max-w-2xl text-center">
          {eyebrow ? (
            <p className="text-sm font-semibold uppercase tracking-widest text-primary">
              {eyebrow}
            </p>
          ) : null}
          <h2 className="mt-2 text-3xl font-bold tracking-tight md:text-4xl lg:text-5xl">
            {title}
          </h2>
          {description ? (
            <p className="mt-4 text-lg leading-8 text-muted-foreground">{description}</p>
          ) : null}
        </div>

        {variant === 'featured' && leader ? (
          <motion.div
            className="mt-12"
            initial={reduceMotion ? false : { opacity: 0, y: 32 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true, amount: 0.2 }}
            transition={{ duration: 0.5 }}
          >
            <FeaturedMember member={leader} />
          </motion.div>
        ) : null}

        {list.length ? (
          <ul
            className={cn(
              'mt-12 grid gap-6',
              variant === 'minimal' ? 'grid-cols-2 gap-y-10' : '',
              columnClasses[columns],
            )}
          >
            {list.map((member, index) => (
              <motion.li
                key={member.name}
                initial={reduceMotion ? false : { opacity: 0, y: 32 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true, amount: 0.2 }}
                transition={{ duration: 0.5, delay: (index % columns) * 0.08 }}
              >
                <Card member={member} />
              </motion.li>
            ))}
          </ul>
        ) : null}

        {action ? (
          <div className="mt-12 flex justify-center">
            <Button asChild size="lg">
              <Link href={action.href}>{action.label}</Link>
            </Button>
          </div>
        ) : null}
      </div>
    </section>
  )
}

import { cn } from '@/lib/utils'

export type TicketPricingCard = {
  id: string
  title: string
  subtitle?: string
  prices?: Array<{ label: string; value: string }>
  highlight?: string
  description?: string
  note?: string
  actions?: Array<{ label: string; href: string; variant?: 'primary' | 'outline' }>
  featured?: boolean
}

export type TicketPricingCardsProps = {
  title?: string
  description?: string
  cards: TicketPricingCard[]
  className?: string
}

export function TicketPricingCards({
  title,
  description,
  cards,
  className,
}: TicketPricingCardsProps) {
  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        {title || description ? (
          <div className="mx-auto mb-12 max-w-2xl text-center">
            {title ? (
              <h2 className="text-3xl font-bold tracking-tight md:text-4xl">{title}</h2>
            ) : null}
            {description ? (
              <p className="mt-4 text-lg leading-8 text-muted-foreground">{description}</p>
            ) : null}
          </div>
        ) : null}
        <ul className="grid gap-6 sm:grid-cols-2 lg:grid-cols-4">
          {cards.map((card) => (
            <li
              key={card.id}
              className={cn(
                'group relative flex flex-col overflow-hidden rounded-3xl border p-6 transition duration-300 hover:-translate-y-2 hover:shadow-2xl',
                card.featured ? 'border-primary bg-primary text-primary-foreground' : 'bg-card',
              )}
            >
              <span
                className={cn(
                  'absolute -right-3 top-1/2 h-6 w-6 -translate-y-1/2 rounded-full',
                  card.featured ? 'bg-background' : 'border bg-background',
                )}
                aria-hidden="true"
              />
              <span
                className={cn(
                  'absolute -left-3 top-1/2 h-6 w-6 -translate-y-1/2 rounded-full',
                  card.featured ? 'bg-background' : 'border bg-background',
                )}
                aria-hidden="true"
              />
              <h3 className="text-xl font-bold uppercase leading-tight tracking-tight">
                {card.title}
              </h3>
              {card.subtitle ? (
                <p
                  className={cn(
                    'mt-2 text-xs font-bold uppercase tracking-widest',
                    card.featured ? 'text-primary-foreground/75' : 'text-primary',
                  )}
                >
                  {card.subtitle}
                </p>
              ) : null}

              <div className="my-6 border-t border-dashed border-current opacity-20" />

              {card.highlight ? (
                <p className="text-6xl font-bold tracking-tight transition group-hover:scale-105">
                  {card.highlight}
                </p>
              ) : null}
              {card.prices?.length ? (
                <dl className="grid gap-4">
                  {card.prices.map((price) => (
                    <div key={price.label}>
                      <dt
                        className={cn(
                          'text-xs font-semibold uppercase tracking-wider',
                          card.featured ? 'text-primary-foreground/75' : 'text-muted-foreground',
                        )}
                      >
                        {price.label}
                      </dt>
                      <dd className="mt-1 text-3xl font-bold">{price.value}</dd>
                    </div>
                  ))}
                </dl>
              ) : null}
              {card.description ? (
                <p
                  className={cn(
                    'mt-4 text-sm leading-6',
                    card.featured ? 'text-primary-foreground/85' : 'text-muted-foreground',
                  )}
                >
                  {card.description}
                </p>
              ) : null}
              {card.note ? <p className="mt-3 text-xs opacity-70">{card.note}</p> : null}

              {card.actions?.length ? (
                <div className="mt-auto flex flex-wrap gap-2 pt-6">
                  {card.actions.map((action) => (
                    <a
                      key={action.label}
                      href={action.href}
                      className={cn(
                        'inline-flex flex-1 justify-center rounded-full px-4 py-2.5 text-sm font-semibold transition',
                        action.variant === 'outline'
                          ? 'border border-current hover:opacity-75'
                          : card.featured
                            ? 'bg-background text-foreground hover:bg-background/90'
                            : 'bg-primary text-primary-foreground hover:bg-primary-hover',
                      )}
                    >
                      {action.label}
                    </a>
                  ))}
                </div>
              ) : null}
            </li>
          ))}
        </ul>
      </div>
    </section>
  )
}

import type { ReactNode } from 'react'

import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

export type CTACenteredCardProps = {
  title: string
  description?: string
  eyebrow?: string
  actions?: ReactNode
  tone?: AccentTone
  /** `primary` ignora o tom e usa o cartão na cor primária do tema. */
  variant?: 'accent' | 'primary'
  className?: string
}

/** Chamada para ação centralizada em cartão com sombra de brilho em gradiente. */
export function CTACenteredCard({
  title,
  description,
  eyebrow,
  actions,
  tone = 'glow',
  variant = 'accent',
  className,
}: CTACenteredCardProps) {
  const t = getAccentTone(tone)
  const isGlow = tone === 'glow'

  if (variant === 'primary') {
    return (
      <section className={cn('w-full bg-background py-12 lg:py-16', className)}>
        <div className="container">
          <div className="mx-auto flex max-w-4xl flex-col items-center gap-6 rounded-2xl bg-primary px-6 py-12 text-center text-primary-foreground shadow-xl shadow-primary/25 sm:px-12">
            {eyebrow ? (
              <span className="text-xs font-semibold uppercase tracking-[0.2em] text-primary-foreground/80">
                {eyebrow}
              </span>
            ) : null}
            <h2 className="text-3xl font-semibold md:text-4xl">{title}</h2>
            {description ? (
              <p className="max-w-2xl text-base leading-relaxed text-primary-foreground/85 md:text-lg">
                {description}
              </p>
            ) : null}
            {actions ? (
              <div className="flex flex-wrap items-center justify-center gap-4">{actions}</div>
            ) : null}
          </div>
        </div>
      </section>
    )
  }

  return (
    <section className={cn('w-full py-12 lg:py-16', t.section, className)}>
      <div className="container">
        <div
          className={cn(
            'mx-auto flex max-w-4xl flex-col items-center gap-6 px-6 py-12 text-center sm:px-12',
            t.panel,
            isGlow
              ? 'rounded-2xl shadow-[0.25rem_0_0.25rem_#86196b,0_0.25rem_0.25rem_#5327b3]'
              : cn('border border-t-4 border-t-amber-500', t.border),
          )}
        >
          {eyebrow ? (
            <span className={cn('text-xs font-semibold uppercase tracking-[0.2em]', t.accent)}>
              {eyebrow}
            </span>
          ) : null}
          <h2 className={cn('text-3xl md:text-4xl', t.heading, isGlow && 'mx-auto')}>{title}</h2>
          {description ? (
            <p className={cn('max-w-2xl text-base leading-relaxed md:text-lg', t.body)}>
              {description}
            </p>
          ) : null}
          {actions ? (
            <div className="flex flex-wrap items-center justify-center gap-4">{actions}</div>
          ) : null}
        </div>
      </div>
    </section>
  )
}

import { HelpCircle } from 'lucide-react'

import { cn } from '@/lib/utils'

export type FAQCardsProps = {
  title?: string
  description?: string
  items: Array<{
    question: string
    answer: React.ReactNode
  }>
  columns?: 2 | 3
  className?: string
}

export function FAQCards({ title, description, items, columns = 3, className }: FAQCardsProps) {
  return (
    <section className={cn('py-16 md:py-24', className)} aria-labelledby="faq-cards-title">
      <div className="container">
        {(title || description) && (
          <header className="mx-auto mb-10 max-w-2xl text-center md:mb-14">
            {title ? (
              <h2 id="faq-cards-title" className="text-3xl font-bold tracking-tight md:text-4xl">
                {title}
              </h2>
            ) : null}
            {description ? (
              <p className="mt-4 text-balance text-muted-foreground">{description}</p>
            ) : null}
          </header>
        )}

        <div className={cn('grid gap-4 md:grid-cols-2', columns === 3 && 'xl:grid-cols-3')}>
          {items.map((item) => (
            <article
              key={item.question}
              className="group rounded-2xl border bg-card p-6 shadow-sm transition duration-300 hover:-translate-y-1 hover:border-primary/30 hover:shadow-lg motion-reduce:transform-none"
            >
              <span className="mb-5 inline-flex size-10 items-center justify-center rounded-xl bg-primary/10 text-primary transition-colors group-hover:bg-primary group-hover:text-primary-foreground">
                <HelpCircle className="size-5" aria-hidden="true" />
              </span>
              <h3 className="text-lg font-semibold leading-snug">{item.question}</h3>
              <div className="mt-3 text-sm leading-6 text-muted-foreground">{item.answer}</div>
            </article>
          ))}
        </div>
      </div>
    </section>
  )
}

import Image from 'next/image'

import { cn } from '@/lib/utils'

export type AccentTestimonial = {
  name: string
  content: string
  role?: string
  avatar?: string
  rating?: number
}

export function TestimonialAvatar({
  name,
  src,
  className,
}: {
  name: string
  src?: string
  className?: string
}) {
  const initials = name
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join('')

  return (
    <span
      className={cn(
        'relative flex h-12 w-12 shrink-0 items-center justify-center overflow-hidden text-sm font-semibold',
        className,
      )}
    >
      {src ? (
        <Image src={src} alt={name} fill sizes="48px" className="object-cover" />
      ) : (
        <span aria-hidden>{initials}</span>
      )}
    </span>
  )
}

import { Marquee } from '@/components/library/motion/Marquee'
import { EyebrowHeading } from '@/components/library/primitives/EyebrowHeading'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

import { TestimonialAvatar, type AccentTestimonial } from './TestimonialAvatar'

export type TestimonialsMarqueeProps = {
  title: string
  testimonials: readonly AccentTestimonial[]
  eyebrow?: string
  description?: string
  speed?: number
  tone?: AccentTone
  className?: string
}

/** Depoimentos em faixa horizontal contínua que pausa no hover. */
export function TestimonialsMarquee({
  title,
  testimonials,
  eyebrow,
  description,
  speed = 45,
  tone = 'glow',
  className,
}: TestimonialsMarqueeProps) {
  const t = getAccentTone(tone)
  const isGlow = tone === 'glow'

  return (
    <section
      className={cn(
        'w-full overflow-hidden py-12 lg:py-16',
        isGlow ? 'bg-[#0e0e0e] text-[#c1c1c1]' : t.section,
        className,
      )}
    >
      <div className="container">
        <EyebrowHeading
          tone={tone}
          eyebrow={eyebrow}
          title={title}
          description={description}
          className="mb-8"
        />
      </div>

      <Marquee speed={speed} gap={32} ariaLabel={title}>
        {testimonials.map((testimonial) => (
          <figure
            key={testimonial.name + testimonial.content}
            className={cn(
              'flex w-[300px] shrink-0 flex-col justify-between gap-6 p-6',
              t.panel,
              isGlow ? 'rounded-md' : cn('border', t.border),
            )}
          >
            <blockquote className={cn('m-0', t.body)}>
              <p>&ldquo;{testimonial.content}&rdquo;</p>
            </blockquote>
            <figcaption className="flex items-center gap-4">
              <span
                className={cn(
                  'p-2',
                  isGlow
                    ? '-rotate-[25deg] rounded-xl bg-[#121212] text-[#ffb0eb]'
                    : 'bg-slate-100 text-amber-600',
                  tone === 'industrial-dark' && 'bg-slate-950 text-amber-500',
                )}
              >
                <TestimonialAvatar
                  name={testimonial.name}
                  src={testimonial.avatar}
                  className={isGlow ? 'rounded-md' : ''}
                />
              </span>
              <span>
                <span className={cn('block font-semibold', t.strong)}>{testimonial.name}</span>
                {testimonial.role ? (
                  <span className={cn('block text-sm', t.muted)}>{testimonial.role}</span>
                ) : null}
              </span>
            </figcaption>
          </figure>
        ))}
      </Marquee>
    </section>
  )
}

import Link from 'next/link'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type HeroVideoProps = {
  title: string
  description?: string
  videoSrc: string
  poster?: string
  action?: { label: string; href: string }
  eyebrow?: string
  className?: string
}

export function HeroVideo({
  title,
  description,
  videoSrc,
  poster,
  action,
  eyebrow,
  className,
}: HeroVideoProps) {
  return (
